"popups/SRMPreQuoteRequest/pqAttachModal.html": "<div class=\"modal-backdrop\" id=\"pqAttachModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pqAttachTitle\" aria-hidden=\"false\" data-ui-defaults=\"{&quot;items&quot;:&quot;unit&quot;}\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"pqAttachTitle\">전달자료 추가</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"srm-kv-grid\">\n          <div class=\"srm-kv-row\"><dt>전달자료 첨부 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><div class=\"form-lookup\"><input type=\"text\" class=\"form-control\" readonly placeholder=\"파일을 첨부해주세요.\"><button type=\"button\" class=\"btn-secondary\">찾아보기</button></div></dd></div>\n          <div class=\"srm-kv-row\"><dt>전달자료 안내</dt><dd><input type=\"text\" class=\"form-control grow\" placeholder=\"50자 이내로 간략히 작성해주세요.\" maxlength=\"50\"></dd></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-primary\" data-close-modal>전달자료 추가</button><button type=\"button\" class=\"btn-secondary\" data-close-modal>취소</button></div>\n    </div>\n  </div>",
